 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name MaxTab_01_OnSelChanged
 * @description Max Tab 01 On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.MaxTab_01_OnSelChanged = async function(nIndex) {
    try {
        if ($c.frame.path("NoData") !== null) {
            await $c.win.closePopup();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05000.MaxTab_01_OnSelChanged" });
    }
};

