/**
 * @method
 * @name dts_EMP_NO_1_OnFilter
 * @description EMP NO 1 On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_EMP_NO_1_OnFilter = function(row) {
    try {
        //  부서코드에  해당하는 사원을 가져온다.
        if (scwin.gDepCd === "") {
            // 전체일 경우 모두 보여준다.
            return true;
        } else {
            if (dts_EMP_NO_1.getCellData(row, "DEP_CD") === scwin.gDepCd || dts_EMP_NO_1.getCellData(row, "DEP_CD") === "") {
                return true;
            } else {
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05000.dts_EMP_NO_1_OnFilter" });
    }
};

