/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        url += "&DEP_CD=" + cmb_DEP_CD_1.getValue();
        url += "&EMP_NO=" + cmb_EMP_NO_1.getValue();
        url += "&UP_DEP_CD=" + js_belngdepcd;
        url += "&LD_MKT_TP_CD=" + scwin.gLdMktTp;
        // alert("vListMdCd :"+vListMdCd);
        const sbmOptions = {
            id : "sbm_dts_List_1",
            action : "/ListedReceive.do",
            ref : "",
            target : "dts_List_1=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        // ShowWin(grd_List_1);

    } else if (MaxTab_01.getSelectedTabIndex() === 2) {
        const cond = scwin.getCondition2();
        // alert ('[cond]'+cond);

        if (chb_main_yn.checked === false && chb_atch_yn.checked === false) {
            await $c.win.alert("제출유형은 한개이상 선택하십시오.");
            chb_main_yn.focus();
            return;
        }
        url += "&ISUR_CD=" + txb_ISUR_CD_2.getValue();
        url += "&FORM_CD=" + cmb_FORM_CD.getValue();
        url += "&ACPT_SDATE=" + edt_AcptSDate.getValue();
        url += "&ACPT_EDATE=" + edt_AcptEDate.getValue();
        url += "&DEP_CD=" + cmb_DEP_CD_2.getValue();
        url += "&EMP_NO=" + cmb_EMP_NO_2.getValue();
        url += "&DISCLS_PROCS_STAT_CD=" + scwin.getCondition2();
        // url += "&DISCLS_PROCS_STAT_CD=" + getObjectValue(cmb_LIST_PROCS_STAT_CD);
        url += "&UP_DEP_CD=" + js_belngdepcd;
        url += "&LD_MKT_TP_CD=" + scwin.gLdMktTp;
        url += "&MAIN_YN=" + chb_main_yn.getValue();
        url += "&ATTCH_YN=" + chb_atch_yn.getValue();
        // alert("vListMdCd :"+vListMdCd);
        const sbmOptions = {
            id : "sbm_dts_List_2",
            action : "/ListedReceive.do",
            ref : "",
            target : "dts_List_2=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    } else if (MaxTab_01.getSelectedTabIndex() === 3) {
        url += "&SS_DEP_CD=" + js_dep_cd;
        url += "&ISUR_CD=" + txb_ISUR_CD_3.getValue();
        url += "&LIST_BZ_TP_CD=" + cmb_LIST_BZ_TP_CD.getValue();
        url += "&BZ_SDATE=" + edt_BzSDate.getValue();
        url += "&BZ_EDATE=" + edt_BzEDate.getValue();
        url += "&DEP_CD=" + cmb_DEP_CD_3.getValue();
        url += "&EMP_NO=" + cmb_EMP_NO_3.getValue();
        url += "&LIST_PROCS_STAT_CD=" + scwin.getCondition3();
        url += "&LD_MKT_TP_CD=" + scwin.gLdMktTp;

        // alert("vListMdCd :"+vListMdCd);
        const sbmOptions = {
            id : "sbm_dts_List_3",
            action : "/ListedReceive.do",
            ref : "",
            target : "dts_List_3=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
