/**
 * @method
 * @name getCondValue
 * @description get Cond Value 처리
 * @param {*} pCnt pCnt
 * @param {*} pVal pVal
 * @param {*} vCode vCode
 * @returns {void}
 * @hidden N
 */
scwin.getCondValue = function(pCnt, pVal, vCode) {
    if (pCnt > 0) {
        pVal += "," + vCode + "";
    } else {
        pVal = vCode;
    }
    return pVal;
};

/**
 * @method
 * @name getCondition2
 * @description get Condition2 처리
 * @returns {void}
 * @hidden N
 */
scwin.getCondition2 = function() {
    let vStatCnt = 0;
    let vStatCond = '';
    if (chb_stat_99.checked === true) {
        vStatCond = '';
        vStatCnt++;
    } else {
        if (chb_stat_00.checked === true) {
            vStatCond = scwin.getCondValue(vStatCnt, vStatCond, '00');
            vStatCnt++;
        }
        if (chb_stat_30.checked === true) {
            vStatCond = scwin.getCondValue(vStatCnt, vStatCond, '30');
            vStatCnt++;
        }
        if (chb_stat_40.checked === true) {
            vStatCond = scwin.getCondValue(vStatCnt, vStatCond, '40');
            vStatCnt++;
        }
        if (scwin.gDepCdCheck === 'Y') {
            if (chb_stat_10.checked === true) {
                vStatCond = scwin.getCondValue(vStatCnt, vStatCond, '10');
                vStatCnt++;
            }
        }
    }
    return vStatCond;
};

/**
 * @method
 * @name getCondition3
 * @description get Condition3 처리
 * @returns {void}
 * @hidden N
 */
scwin.getCondition3 = function() {
    let vStatCnt = 0;
    let vStatCond = '';
    if (chb_bzstat_99.checked === true) {
        vStatCond = '';
        vStatCnt++;
    } else {
        if (chb_bzstat_20.checked === true) {
            vStatCond = scwin.getCondValue(vStatCnt, vStatCond, '20');
            vStatCnt++;
        }
        if (chb_bzstat_22.checked === true) {
            vStatCond = scwin.getCondValue(vStatCnt, vStatCond, '22');
            vStatCnt++;
        }
    }
    return vStatCond;
};

/**
 * @method
 * @name openDetail
 * @description 클릭된 값 변수에 셋팅
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDetail = async function(row, colid) {
    scwin.setContnId(row);
    if (colid === "FORM_KOR_NM") {
        await $c.stf.openDisclViewer(scwin.gAcptNo, scwin.gViewerStat);
    } else if (colid === "ACPT_DDTM") {
        $c.stf.openDisclAllList();
    } else if (colid === "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    }
};

/**
 * @method
 * @name setContnId
 * @description set Contn Id 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gViewerStat = "R"; // 처리시 뷰어=P,  조회시 뷰어=R
    if (Number(obj) > 0) {
        // 그리드에서 선택시
        if (MaxTab_01.getSelectedTabIndex() === 1) {
            scwin.gAcptNo = dts_List_1.getCellData(Number(obj), "ACPT_NO");
            scwin.gMainFormCd = dts_List_1.getCellData(Number(obj), "FORM_CD");
            scwin.gFormVer = dts_List_1.getCellData(Number(obj), "FORM_VER");
            scwin.gIsurCd = dts_List_1.getCellData(Number(obj), "ISUR_CD");

            // 수익증권신청서는 공시3팀-->유가 공시지원TF팀 변경(2660, 20210312)
            if (scwin.gMainFormCd === '68904' || scwin.gMainFormCd === '68905' || scwin.gMainFormCd === '68928') {
                // if (js_dep_cd == '2630') {//공시3팀
                // 2021-02-22 2611 -> 2650
                // 2021-03-12 2650-> 2660
                // 2022-01-21 2660-> 2620
                // 2024-01-26 2620-> 2611
                if (js_dep_cd === '2611' || js_dep_cd === '2600') {
                    scwin.gViewerStat = "P"; // 처리시 뷰어=P,  조회시 뷰어=R

                }
            } else {
                scwin.gViewerStat = "P"; // 처리시 뷰어=P,  조회시 뷰어=R

            }
        } else if (MaxTab_01.getSelectedTabIndex() === 2) {
            scwin.gAcptNo = dts_List_2.getCellData(Number(obj), "ACPT_NO");
            scwin.gMainFormCd = dts_List_2.getCellData(Number(obj), "FORM_CD");
            scwin.gFormVer = dts_List_2.getCellData(Number(obj), "FORM_VER");
            scwin.gIsurCd = dts_List_2.getCellData(Number(obj), "ISUR_CD");
            scwin.gApprovYn = dts_List_2.getCellData(Number(obj), "APPROVYN");
            if (scwin.gApprovYn === 'Y') {
                // 유가 공시부일경우
                scwin.gViewerStat = "P"; // 처리시 뷰어=P,  조회시 뷰어=R

            }
        } else if (MaxTab_01.getSelectedTabIndex() === 3) {
            scwin.gIsurCd = dts_List_3.getCellData(Number(obj), "ISUR_CD");
        }
    }
};

/**
 * @method
 * @name excelDown
 * @description 엑셀 로그
 * @returns {void}
 * @hidden N
 */
scwin.excelDown = function() {
    // 엑셀 로그
    $c.stf.doLogSave("ULDSTF05000.xml", SCREN_PROCS_TP_CD_07);
    if (MaxTab_01.getSelectedTabIndex() === 2) {
        // grd_List_2.GridToExcel("접수처리목록", "", "2");
        $c.data.downloadGridViewOffice(grd_List_2, "접수처리목록", "", 8, 0);
    } else if (MaxTab_01.getSelectedTabIndex() === 3) {
        // grd_List_3.GridToExcel("업무처리목록", "", "8");
        $c.data.downloadGridViewOffice(grd_List_3, "업무처리목록", "", 8, 0);
    }
};
